-- Leone Rock Premier League — RESET PREFLIGHT (READ-ONLY)
-- Run this BEFORE any reset in the Supabase SQL Editor.
-- This script DOES NOT DELETE, UPDATE, INSERT, or ALTER any data.
-- Save/export the result before preparing a targeted reset.
--
-- Purpose:
-- 1) Identify actual public tables present in this Supabase project.
-- 2) Count rows so test-data tables can be identified.
-- 3) Review foreign-key relationships before deletion.
--
-- IMPORTANT:
-- Row counts are generated by COUNT(*) queries. Run during a quiet period.
-- Do not use a blanket TRUNCATE/CASCADE reset. Keep auth.users and the
-- General Overseer / Super Admin profile and role assignments.

-- A. Public tables and their current row counts.
DO $preflight$
DECLARE
  t record;
  n bigint;
BEGIN
  CREATE TEMP TABLE IF NOT EXISTS reset_preflight_row_counts (
    schema_name text,
    table_name text,
    row_count bigint
  ) ON COMMIT PRESERVE ROWS;

  TRUNCATE TABLE reset_preflight_row_counts;

  FOR t IN
    SELECT table_schema, table_name
    FROM information_schema.tables
    WHERE table_schema = 'public'
      AND table_type = 'BASE TABLE'
    ORDER BY table_name
  LOOP
    EXECUTE format('SELECT count(*) FROM %I.%I', t.table_schema, t.table_name)
      INTO n;
    INSERT INTO reset_preflight_row_counts
      VALUES (t.table_schema, t.table_name, n);
  END LOOP;
END
$preflight$;

SELECT schema_name, table_name, row_count
FROM reset_preflight_row_counts
ORDER BY table_name;

-- B. Foreign-key map: identifies safe deletion order and dependent tables.
SELECT
  tc.table_schema,
  tc.table_name AS child_table,
  kcu.column_name AS child_column,
  ccu.table_schema AS parent_schema,
  ccu.table_name AS parent_table,
  ccu.column_name AS parent_column,
  rc.delete_rule
FROM information_schema.table_constraints tc
JOIN information_schema.key_column_usage kcu
  ON tc.constraint_catalog = kcu.constraint_catalog
 AND tc.constraint_schema = kcu.constraint_schema
 AND tc.constraint_name = kcu.constraint_name
JOIN information_schema.constraint_column_usage ccu
  ON ccu.constraint_catalog = tc.constraint_catalog
 AND ccu.constraint_schema = tc.constraint_schema
 AND ccu.constraint_name = tc.constraint_name
JOIN information_schema.referential_constraints rc
  ON rc.constraint_catalog = tc.constraint_catalog
 AND rc.constraint_schema = tc.constraint_schema
 AND rc.constraint_name = tc.constraint_name
WHERE tc.constraint_type = 'FOREIGN KEY'
  AND tc.table_schema = 'public'
ORDER BY parent_table, child_table, tc.constraint_name;

-- C. Roles/profile summary (read-only; inspect exact columns first).
SELECT table_name, column_name, data_type
FROM information_schema.columns
WHERE table_schema = 'public'
  AND table_name IN ('user_profiles', 'club_registration_applications',
                     'league_clubs', 'matches', 'match_results',
                     'league_standings', 'app_settings')
ORDER BY table_name, ordinal_position;

-- STOP HERE. No records have been changed by this script.
-- Export the results of sections A, B, and C before drafting the reset SQL.
